import Foundation

/// Represents a single emoji, its aliases, keywords, and Unicode metadata.
public struct EmojiItem: Sendable, Equatable, Hashable, Identifiable {
    public var id: String { "\(emoji)_\(name)" }
    public let emoji: String
    public let name: String
    public let aliases: [String]
    public let category: String
    public let keywords: [String]

    public var primaryAlias: String {
        aliases.first ?? ":\(name.lowercased().replacingOccurrences(of: " ", with: "_")):"
    }

    public var unicodeHex: String {
        emoji.unicodeScalars.map { String(format: "U+%04X", $0.value) }.joined(separator: " ")
    }

    public init(
        emoji: String,
        name: String,
        aliases: [String],
        category: String = "Smileys",
        keywords: [String] = []
    ) {
        self.emoji = emoji
        self.name = name
        self.aliases = aliases
        self.category = category
        self.keywords = keywords
    }
}

/// Catalog of 1,700+ standard macOS emojis, trigger codes, and multi-word smart search.
public enum EmojiCatalog {
    public struct Match: Sendable, Equatable {
        public let emoji: String
        public let alias: String
    }

    public static let categories: [String] = [
        "All", "Popular", "Smileys", "Gestures", "Nature", "Food", "Travel", "Celebration", "Objects", "Symbols", "Flags"
    ]

    private static let rawData = ""

    /// Master list of all emojis with expressive synonyms.
    public static let all: [EmojiItem] = {
        guard let data = Data(base64Encoded: rawData),
              let text = String(data: data, encoding: .utf8) else {
            return []
        }
        var items: [EmojiItem] = []
        items.reserveCapacity(1800)
        for line in text.components(separatedBy: "\n") {
            let parts = line.components(separatedBy: "\t")
            guard parts.count >= 5 else { continue }
            let emoji = parts[0]
            let name = parts[1]
            let aliases = parts[2].components(separatedBy: ",")
            let category = parts[3]
            let keywords = parts[4].components(separatedBy: ",")
            items.append(EmojiItem(emoji: emoji, name: name, aliases: aliases, category: category, keywords: keywords))
        }
        return items
    }()

    /// Inverted dictionary for sub-millisecond lookup from alias to emoji.
    private static let lookupTable: [String: String] = {
        var table: [String: String] = [:]
        for item in all {
            for alias in item.aliases {
                table[alias.lowercased()] = item.emoji
            }
        }
        return table
    }()

    /// Strips variation selectors (\u{FE0F}) and whitespace to normalize comparison across apps.
    public static func normalizeEmoji(_ s: String) -> String {
        s.replacingOccurrences(of: "\u{FE0F}", with: "").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// Matches the end of a typed keystroke buffer against all known emoji aliases.
    public static func findMatch(in buffer: String) -> Match? {
        guard buffer.hasSuffix(":") && buffer.count >= 3 else { return nil }

        let maxSearchLength = min(buffer.count, 32)
        let searchSlice = buffer.suffix(maxSearchLength)

        for (alias, emoji) in lookupTable {
            if searchSlice.hasSuffix(alias) {
                return Match(emoji: emoji, alias: alias)
            }
        }
        return nil
    }

    /// Reverse-engineers any emoji (whether in curated catalog or pasted from WhatsApp/web).
    public static func reverseEngineer(input: String) -> EmojiItem? {
        let trimmed = input.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        let normalizedInput = normalizeEmoji(trimmed)

        // 1. Direct match in curated catalog
        if let direct = all.first(where: {
            $0.emoji == trimmed || normalizeEmoji($0.emoji) == normalizedInput
        }) {
            return direct
        }

        // 2. Check if the string contains emoji scalars
        let hasEmojiScalar = trimmed.unicodeScalars.contains { $0.properties.isEmoji || $0.properties.isEmojiPresentation }
        if hasEmojiScalar {
            let hex = trimmed.unicodeScalars.map { String(format: "U+%04X", $0.value) }.joined(separator: " ")
            let firstScalar = trimmed.unicodeScalars.first?.value ?? 0
            let autoAlias = ":emoji_\(String(format: "%x", firstScalar)):"
            return EmojiItem(
                emoji: trimmed,
                name: "Pasted Emoji (\(hex))",
                aliases: [autoAlias],
                category: "Custom",
                keywords: ["custom", "pasted"]
            )
        }

        return nil
    }

    /// Smart multi-word search, keyword matching, and frequency ranking.
    public static func filter(
        query: String,
        category: String? = nil,
        usageCounts: [String: Int] = [:]
    ) -> [EmojiItem] {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let baseItems: [EmojiItem]
        if let cat = category, !cat.isEmpty && cat != "All" {
            baseItems = all.filter { $0.category.localizedCaseInsensitiveCompare(cat) == .orderedSame }
        } else {
            baseItems = all
        }

        // Empty query: sort by usage count first, then default order
        if trimmed.isEmpty {
            return baseItems.sorted { item1, item2 in
                let count1 = usageCounts[item1.emoji] ?? 0
                let count2 = usageCounts[item2.emoji] ?? 0
                if count1 != count2 { return count1 > count2 }
                return false
            }
        }

        // Direct emoji paste match / reverse engineer (e.g. user pasted "🌹" or "👍")
        if let direct = reverseEngineer(input: trimmed) {
            let others = baseItems.filter { $0.id != direct.id }
            return [direct] + others
        }

        let clean = trimmed.lowercased().replacingOccurrences(of: ":", with: "")
        let condensed = clean.replacingOccurrences(of: "_", with: "").replacingOccurrences(of: "-", with: "").replacingOccurrences(of: " ", with: "")
        let queryWords = clean.split(whereSeparator: { $0.isWhitespace || $0 == "_" || $0 == "-" }).map(String.init)

        var scoredItems: [(item: EmojiItem, score: Int)] = []

        for item in baseItems {
            var score = 0
            let itemNameLower = item.name.lowercased()
            let itemCondensedName = itemNameLower.replacingOccurrences(of: "_", with: "").replacingOccurrences(of: "-", with: "").replacingOccurrences(of: " ", with: "")

            // 1. Exact alias match (e.g. "thumbs_up" or "thumbsup")
            if item.aliases.contains(where: {
                let stripped = $0.trimmingCharacters(in: CharacterSet(charactersIn: ":")).lowercased()
                let strippedCondensed = stripped.replacingOccurrences(of: "_", with: "").replacingOccurrences(of: "-", with: "")
                return stripped == clean || strippedCondensed == condensed
            }) {
                score += 2000
            }

            // 2. Exact name match
            if itemNameLower == clean || itemCondensedName == condensed {
                score += 1800
            }

            // 3. Name prefix match
            if itemNameLower.hasPrefix(clean) || itemCondensedName.hasPrefix(condensed) {
                score += 1400
            }

            // 4. Alias prefix match
            if item.aliases.contains(where: {
                let stripped = $0.trimmingCharacters(in: CharacterSet(charactersIn: ":")).lowercased()
                return stripped.hasPrefix(clean) || stripped.replacingOccurrences(of: "_", with: "").hasPrefix(condensed)
            }) {
                score += 1200
            }

            // 5. All query words match in name or keywords
            if !queryWords.isEmpty {
                let allWordsMatch = queryWords.allSatisfy { word in
                    itemNameLower.contains(word) ||
                    item.keywords.contains(where: { $0.contains(word) }) ||
                    item.aliases.contains(where: { $0.contains(word) })
                }
                if allWordsMatch {
                    score += 1000
                }
            }

            // 6. Partial keyword or name substring match
            for word in queryWords {
                if item.keywords.contains(where: { $0 == word }) {
                    score += 500
                } else if item.keywords.contains(where: { $0.contains(word) }) {
                    score += 250
                }
            }

            if itemNameLower.contains(clean) {
                score += 350
            }

            // 7. Usage frequency bonus
            if let usage = usageCounts[item.emoji], usage > 0 {
                score += min(usage * 20, 500)
            }

            if score > 0 {
                scoredItems.append((item, score))
            }
        }

        return scoredItems.sorted { $0.score > $1.score }.map(\.item)
    }
}
